thin-boundaries.source:
MILKDROP_PRESET_VERSION=201
PSVERSION_WARP=2
PSVERSION_COMP=2
[preset00]
fGammaAdj=1
fDecay=0
fVideoEchoAlpha=0
fWaveAlpha=0
ob_a=0
ib_a=0
mv_a=0
zoom=1
rot=0
warp=0
wavecode_0_enabled=1
wavecode_0_samples=100
wavecode_0_bSpectrum=0
wavecode_0_bUseDots=1
wavecode_0_bDrawThick=0
wavecode_0_bAdditive=0
wavecode_0_smoothing=0
wavecode_0_r=1
wavecode_0_g=1
wavecode_0_b=1
wavecode_0_a=1
wave_0_per_point1=k=int(sample*99+0.5);
wave_0_per_point2=rr=int(k/10);cc=if(equal(rr%2,0),k%10,9-k%10);
wave_0_per_point3=ox=if(equal(k%9,0),-0.501,if(equal(k%9,1),-0.5,if(equal(k%9,2),-0.499,if(equal(k%9,3),-0.001,if(equal(k%9,4),0,if(equal(k%9,5),0.001,if(equal(k%9,6),0.499,if(equal(k%9,7),0.5,0.501))))))));
wave_0_per_point4=oy=if(equal((k*4)%9,0),-0.501,if(equal((k*4)%9,1),-0.5,if(equal((k*4)%9,2),-0.499,if(equal((k*4)%9,3),-0.001,if(equal((k*4)%9,4),0,if(equal((k*4)%9,5),0.001,if(equal((k*4)%9,6),0.499,if(equal((k*4)%9,7),0.5,0.501))))))));
wave_0_per_point5=x=(18+22*cc+ox)/256;
wave_0_per_point6=y=0.5+(0.5-(18+12*rr+oy)/144)*0.5625;
wave_0_per_point7=r=(32+(k%8)*24)/255;
wave_0_per_point8=g=(32+(int(k/8)%8)*24)/255;
wave_0_per_point9=b=(64+(k%5)*32)/255;a=1;
warp_1=`shader_body {ret=0;}
comp_1=`shader_body {ret=GetPixel(uv);}

